@pytest.mark.browser @pytest.mark.skipif( __import__("sys").platform != "linux", reason="Linux live browser descendant crashes", ) @pytest.mark.parametrize("target", ["browser", "renderer"]) def test_live_browser_crash_releases_tree_and_recovers(site, target): async def run(): manager = SessionManager( max_sessions=1, allow_networks=("127.0.0.1/32",), resource_limits=ResourceLimits(processes=256), ) sid = await manager.create("owner") descendants = [] try: snapshot = await manager.call( "owner", sid, "navigate", site + "/form", force_fidelity=True ) assert snapshot.get("success"), snapshot worker = psutil.Process(manager._sessions[sid].worker.pid) descendants = worker.children(recursive=True) chromes = [p for p in descendants if p.name() in ("chrome", "chromium")] selected = ( [ p for p in chromes if ("--type=renderer" in p.cmdline()) if target == "renderer" ] if target == "renderer" else [ next( p for p in chromes if not any(a.startswith("--type=") for a in p.cmdline()) ) ] ) # Chromium can prestart a spare renderer; terminate every session renderer # so this test cannot accidentally kill only the spare process. assert selected for process in selected: try: process.kill() except psutil.NoSuchProcess: pass await asyncio.sleep(0.1) aid = next(a["id"] for a in snapshot["actions"] if a["label"] == "Name") result = await manager.call( "owner", sid, "fill", aid, "must not target another page", snapshot["generation"], ) assert not result.get("success"), result assert result["error"]["code"] in { "STALE_ACTION_ID", "PAGE_NAVIGATED", "NO_ACTIVE_PAGE", "WORKER_CRASHED", "SNAPSHOT_FAILED", }, result assert (await manager.close("owner", sid))["success"] assert manager.active_sessions == 0 for process in descendants: try: assert process.status() == psutil.STATUS_ZOMBIE, ( process.pid, process.name(), process.status(), ) except psutil.NoSuchProcess: pass replacement = await manager.create("owner") fresh = await manager.call( "owner", replacement, "navigate", site + "/form", force_fidelity=True ) assert fresh.get("success"), fresh assert fresh["generation"] != snapshot["generation"] finally: await manager.close_all()
